import { useState, useEffect } from 'react';
import PocketBase from 'pocketbase';

const pb = new PocketBase('https://api.delta-aesthetics.com');

export default function AdminDashboard() {
  const [authenticated, setAuthenticated] = useState(false);
    const [email, setEmail] = useState('');
      const [password, setPassword] = useState('');
        const [bookings, setBookings] = useState([]);
          const [loading, setLoading] = useState(false);
            const [error, setError] = useState('');

              useEffect(() => {
                  if (pb.authStore.isValid && pb.authStore.model?.collectionName === '_superusers') {
                        setAuthenticated(true);
                              loadAdminData();
                                  }
                                    }, []);

                                      const handleAdminLogin = async (e) => {
                                          e.preventDefault();
                                              setLoading(true);
                                                  setError('');
                                                      try {
                                                            await pb.collection('_superusers').authWithPassword(email, password);
                                                                  setAuthenticated(true);
                                                                        loadAdminData();
                                                                            } catch (err) {
                                                                                  setError('Invalid operator credentials.');
                                                                                      } finally {
                                                                                            setLoading(false);
                                                                                                }
                                                                                                  };

                                                                                                    const loadAdminData = async () => {
                                                                                                        try {
                                                                                                              const records = await pb.collection('bookings').getFullList({ sort: '-booking_date' });
                                                                                                                    setBookings(records);
                                                                                                                        } catch (err) {
                                                                                                                              console.error('Failed to load queue:', err);
                                                                                                                                  }
                                                                                                                                    };

                                                                                                                                      if (!authenticated) {
                                                                                                                                          return (
                                                                                                                                                <div className="max-w-md mx-auto p-6 bg-[#090D16] border border-gray-800 rounded-xl text-white">
                                                                                                                                                        <h2 className="text-xl font-bold mb-2">Practice Staff Login</h2>
                                                                                                                                                                <p className="text-sm text-gray-400 mb-6">Restricted operator dashboard access.</p>
                                                                                                                                                                        <form onSubmit={handleAdminLogin} className="space-y-4">
                                                                                                                                                                                  <input
                                                                                                                                                                                              type="email"
                                                                                                                                                                                                          required
                                                                                                                                                                                                                      placeholder="admin@delta-aesthetics.com"
                                                                                                                                                                                                                                  value={email}
                                                                                                                                                                                                                                              onChange={(e) => setEmail(e.target.value)}
                                                                                                                                                                                                                                                          className="w-full p-3 bg-[#030712] border border-gray-800 rounded-lg text-white focus:border-[#55CDFC] outline-none"
                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                              <input
                                                                                                                                                                                                                                                                                          type="password"
                                                                                                                                                                                                                                                                                                      required
                                                                                                                                                                                                                                                                                                                  placeholder="Password"
                                                                                                                                                                                                                                                                                                                              value={password}
                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setPassword(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                      className="w-full p-3 bg-[#030712] border border-gray-800 rounded-lg text-white focus:border-[#55CDFC] outline-none"
                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                          {error && <p className="text-red-400 text-xs">{error}</p>}
                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                type="submit"
                                                                                                                                                                                                                                                                                                                                                                                                            disabled={loading}
                                                                                                                                                                                                                                                                                                                                                                                                                        className="w-full py-3 bg-[#55CDFC] hover:bg-[#F7A8B8] text-black font-semibold rounded-lg transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                              {loading ? 'Authenticating...' : 'Sign In as Staff'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="max-w-6xl mx-auto space-y-6 text-white">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex justify-between items-center bg-[#090D16] p-6 border border-gray-800 rounded-xl">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h1 className="text-2xl font-bold">Practice Management Dashboard</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="text-sm text-gray-400">Operator: {pb.authStore.model?.email}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onClick={() => { pb.authStore.clear(); setAuthenticated(false); }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="px-4 py-2 border border-gray-700 hover:bg-gray-800 rounded-lg text-sm transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Sign Out
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="bg-[#090D16] p-6 border border-gray-800 rounded-xl">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h2 className="text-lg font-semibold mb-4">Master Booking Queue</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="overflow-x-auto">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <table className="w-full text-left text-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <thead className="border-b border-gray-800 text-gray-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="pb-3">Client Name</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="pb-3">Email</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="pb-3">Booking Date</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="pb-3">Short Notice</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="pb-3">Status</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <tbody className="divide-y divide-gray-800/50">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {bookings.map((b) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr key={b.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td className="py-4 font-medium">{b.customer_name}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td className="py-4 text-gray-400">{b.customer_email}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td className="py-4">{new Date(b.booking_date).toLocaleString()}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td className="py-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {b.accepts_short_notice ? <span className="text-xs bg-purple-900/40 text-purple-300 px-2 py-0.5 rounded">Opted-in</span> : 'Standard'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td className="py-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span className={`px-2.5 py-1 rounded-full text-xs ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                b.status === 'cancelled' ? 'bg-red-900/30 text-red-400 border border-red-800' : 'bg-emerald-900/30 text-emerald-400 border border-emerald-800'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {b.status || 'confirmed'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }